diff --git a/packages/imessage/src/remote/client.ts b/packages/imessage/src/remote/client.ts
index 4fff682..6e82201 100644
--- a/packages/imessage/src/remote/client.ts
+++ b/packages/imessage/src/remote/client.ts
@@ -1,6 +1,38 @@
 import type { AdvancedIMessage } from "@photon-ai/advanced-imessage";
+import type { Store } from "@spectrum-ts/core";
 import { type RemoteClient, SHARED_PHONE } from "../types";

+const CLIENTS_KEY = "imessage.clients";
+
+/**
+ * Stash the outbound `RemoteClient[]` on the per-platform `store`
+ * (`createClient` returns the bare fusor brand, so the store is where
+ * outbound state lives — the doc's `initClient`/`getClient` pattern). The
+ * array object is stored once and never replaced, so the WeakMap-keyed
+ * caches (auth, message/poll, seen-events) keep their identity key.
+ */
+export const initClients = (
+  store: Store,
+  clients: RemoteClient[]
+): RemoteClient[] => {
+  store.set(CLIENTS_KEY, clients);
+  return clients;
+};
+
+/** The store-held clients, or `undefined` before `createClient` ran. */
+export const peekClients = (store: Store): RemoteClient[] | undefined =>
+  store.array<RemoteClient>(CLIENTS_KEY);
+
+export const getClients = (store: Store): RemoteClient[] => {
+  const clients = peekClients(store);
+  if (!clients) {
+    throw new Error(
+      "iMessage clients not initialized — lifecycle.createClient has not run"
+    );
+  }
+  return clients;
+};
+
 export const isSharedMode = (clients: RemoteClient[]): boolean =>
   clients.length === 1 && clients[0]?.phone === SHARED_PHONE;

