2	  headers: Record<string, string>;
3	  method: string;
4	  path: string;
5	  rawBody: Uint8Array;
6	}
7	
8	const CR = 0x0d;
9	const LF = 0x0a;
10	
11	function findHeaderEnd(bytes: Uint8Array): number {
12	  for (let i = 0; i + 3 < bytes.length; i++) {
13	    if (
14	      bytes[i] === CR &&
15	      bytes[i + 1] === LF &&
16	      bytes[i + 2] === CR &&
17	      bytes[i + 3] === LF
18	    ) {
19	      return i;
20	    }
21	  }
22	  return -1;
23	}
24	
25	/**
26	 * Parses an HTTP/1.1 wire-format request out of `raw_request` from
27	 * `RawInboundEvent`. Headers are lowercased. Multiple header values with the
28	 * same name are joined with ", " (RFC 7230 §3.2.2).
29	 */
30	export function parseHttpRequest(bytes: Uint8Array): ParsedHttpRequest {
31	  const headerEnd = findHeaderEnd(bytes);
32	  if (headerEnd < 0) {
33	    throw new Error("fusor: raw_request missing CRLFCRLF header terminator");
34	  }
35	  const headerText = new TextDecoder("utf-8").decode(
36	    bytes.subarray(0, headerEnd)
37	  );
38	  const rawBody = bytes.subarray(headerEnd + 4);
39	
40	  const lines = headerText.split("\r\n");
41	  const requestLine = lines[0];
42	  if (!requestLine) {
43	    throw new Error("fusor: raw_request missing request line");
44	  }
45	
46	  const firstSpace = requestLine.indexOf(" ");
47	  const lastSpace = requestLine.lastIndexOf(" ");
48	  if (firstSpace < 0 || lastSpace <= firstSpace) {
49	    throw new Error(`fusor: malformed request line: ${requestLine}`);
50	  }
51	  const method = requestLine.slice(0, firstSpace);
52	  const path = requestLine.slice(firstSpace + 1, lastSpace);
53	
54	  const headers: Record<string, string> = {};
55	  for (let i = 1; i < lines.length; i++) {
56	    const line = lines[i];
57	    if (!line) {
58	      continue;
59	    }
60	    const colon = line.indexOf(":");
61	    if (colon < 0) {
62	      continue;
63	    }
64	    const key = line.slice(0, colon).trim().toLowerCase();
65	    const value = line.slice(colon + 1).trim();
66	    if (!key) {
67	      continue;
68	    }
69	    const existing = headers[key];
70	    headers[key] = existing ? `${existing}, ${value}` : value;
71	  }
72	
73	  return { method, path, headers, rawBody };
74	}
