2	import { RawInboundEvent } from "@photon-ai/proto/photon/fusor/v1/inbound";
3	
4	// Mock iMessage→Fusor publisher: builds the exact wire artifacts the real
5	// publishers (spectrum-imessage / a dedicated tap) will emit per
6	// packages/imessage/src/fusor/ENVELOPE.md, so the whole consumer path is
7	// testable with no backend. Typed structurally (no import from
8	// @spectrum-ts/imessage — it dev-depends on this package).
9	
10	export const IMESSAGE_FUSOR_PLATFORM = "imessage";
11	
12	export interface IMessageEnvelopeInput {
13	  event: Record<string, unknown>;
14	  eventId?: string;
15	  kind: "message" | "poll" | "group" | "chat";
16	  line?: string;
17	  projectId?: string;
18	  schemaVersion?: number;
19	  sequence?: number | string;
20	}
21	
22	/**
23	 * Inner-envelope signing options (ENVELOPE.md §Signature): HMAC-SHA256 over
24	 * `{ts}.{body}` carried as `x-imessage-timestamp` / `x-imessage-signature`.
25	 * `timestampSec` defaults to now; pass a stale value to test the replay
26	 * guard, or `signature` to force a mismatching header.
27	 */
28	export interface IMessageSignOptions {
29	  secret: string;
30	  signature?: string;
31	  timestampSec?: number;
32	}
33	
34	interface BuiltEnvelope {
35	  body: Record<string, unknown>;
36	  eventId: string;
37	}
38	
39	const buildEnvelope = (input: IMessageEnvelopeInput): BuiltEnvelope => {
40	  const eventId = input.eventId ?? `im-test-${input.sequence ?? 1}`;
41	  return {
42	    eventId,
43	    body: {
44	      schemaVersion: input.schemaVersion ?? 1,
45	      eventId,
46	      ...(input.projectId && { projectId: input.projectId }),
47	      line: input.line ?? "shared",
48	      sequence: String(input.sequence ?? 1),
49	      kind: input.kind,
50	      event: input.event,
51	    },
52	  };
53	};
54	
55	const MS_PER_SEC = 1000;
56	
57	const signatureHeaders = (
58	  bodyText: string,
59	  sign: IMessageSignOptions
60	): string => {
61	  const ts = sign.timestampSec ?? Math.floor(Date.now() / MS_PER_SEC);
62	  const sig =
63	    sign.signature ??
64	    createHmac("sha256", sign.secret).update(`${ts}.${bodyText}`).digest("hex");
65	  return `x-imessage-timestamp: ${ts}\r\nx-imessage-signature: ${sig}\r\n`;
66	};
67	
68	/**
69	 * The synthetic HTTP/1.1 request string carried in RawInboundEvent.rawRequest
70	 * — exposed separately for driving a fusor ws test server's event frames.
71	 * Pass `sign` to emit the signed variant (what a secret-configured publisher
72	 * sends).
73	 */
74	export const imessageEnvelopeHttp = (
75	  input: IMessageEnvelopeInput,
76	  sign?: IMessageSignOptions
77	): string => {
78	  const { body } = buildEnvelope(input);
79	  const bodyText = JSON.stringify(body);
80	  const version = input.schemaVersion ?? 1;
81	  const signed = sign ? signatureHeaders(bodyText, sign) : "";
82	  return `POST /imessage HTTP/1.1\r\ncontent-type: application/json\r\nx-imessage-schema-version: ${version}\r\n${signed}\r\n${bodyText}`;
83	};
84	
85	/** The full protobuf webhook body fusor delivers (RawInboundEvent bytes). */
86	export const encodeIMessageEnvelope = (
87	  input: IMessageEnvelopeInput,
88	  sign?: IMessageSignOptions
89	): Uint8Array => {
90	  const { eventId } = buildEnvelope(input);
91	  return RawInboundEvent.encode(
92	    RawInboundEvent.create({
93	      eventId,
94	      projectId: input.projectId ?? "proj",
95	      platform: IMESSAGE_FUSOR_PLATFORM,
96	      rawRequest: new TextEncoder().encode(imessageEnvelopeHttp(input, sign)),
97	    })
98	  ).finish();
99	};
